package com.chesspulseai.controller; import com.chesspulseai.engine.*; import com.chesspulseai.service.*; import com.chesspulseai.dto.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.constraints.NotBlank;
@RestController @RequestMapping("/api/analysis") public class AnalysisController {private final StockfishClient engine;private final ProbabilityService probability;private final GamePhaseDetector phase;public AnalysisController(StockfishClient e,ProbabilityService p,GamePhaseDetector g){engine=e;probability=p;phase=g;} @PostMapping("/evaluate") public AnalysisResponse evaluate(@RequestBody @NotBlank String fen){EngineEvaluation e=engine.evaluate(fen);return new AnalysisResponse(e.centipawns(),e.mateScore(),e.bestMove(),e.principalVariation(),e.depth(),probability.from(e.centipawns(),e.mateScore()),phase.detect(fen),null);}}
